CREATE TABLE IF NOT EXISTS shop_bank_order(order_id BIGINT PRIMARY KEY, confirmed BIGINT NOT NULL DEFAULT 0, started_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS shop_bank_receipt(id BIGINT PRIMARY KEY AUTO_INCREMENT,order_id BIGINT NOT NULL,submitted_by BIGINT NOT NULL,submitted_account VARCHAR(40) NOT NULL,request_key VARCHAR(80) NOT NULL,amount BIGINT NOT NULL,proof VARCHAR(200) NOT NULL,payer VARCHAR(100) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'pending',confirmed_amount BIGINT NOT NULL DEFAULT 0,bank_reference VARCHAR(120) NULL UNIQUE,note VARCHAR(300) NULL,reviewer VARCHAR(64) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY bank_request(submitted_by,request_key));
CREATE TABLE IF NOT EXISTS shop_bank_refund(id BIGINT PRIMARY KEY AUTO_INCREMENT,order_id BIGINT NOT NULL,case_id BIGINT NULL,source_key VARCHAR(100) NOT NULL UNIQUE,amount BIGINT NOT NULL,reason VARCHAR(150) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'pending',bank_reference VARCHAR(120) NULL UNIQUE,note VARCHAR(300) NULL,operator_name VARCHAR(64) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
INSERT IGNORE INTO shop_config(config_key,content) VALUES('bank-transfer','{"enabled":false,"companyName":"","bankName":"","accountNumber":"","waitHours":24}');

CREATE TABLE IF NOT EXISTS shop_bank_movement(reference_no VARCHAR(120) PRIMARY KEY,direction VARCHAR(10) NOT NULL,source_key VARCHAR(100) NOT NULL UNIQUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
